describe('Form Validation Error Messages', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should display a specific validation error for an empty name field', () => {
        cy.get('input[name="name"]').clear();
        cy.get('form').submit();
        cy.get('.error-message').should('contain', 'Name is required');
    });

    it('should display a specific validation error for an invalid email format', () => {
        cy.get('input[name="email"]').type('invalid-email');
        cy.get('form').submit();
        cy.get('.error-message').should('contain', 'Email is not valid');
    });
});
